# S3 生命周期策略示例
apiVersion: v1
kind: ConfigMap
metadata:
  name: backup-lifecycle-policy
  namespace: velero
data:
  lifecycle.json: |
    {
      "Rules": [
        {
          "ID": "BackupLifecycle",
          "Status": "Enabled",
          "Transitions": [
            {
              "Days": 30,
              "StorageClass": "STANDARD_IA"
            },
            {
              "Days": 90,
              "StorageClass": "GLACIER"
            }
          ],
          "Expiration": {
            "Days": 365
          }
        }
      ]
    }
